 61→            long queryStartTime = System.currentTimeMillis(); // 쿼리 시작 시간
 62→            PreparedStatement preparedStatement = connection.prepareStatement(selectSql, ResultSet.TYPE_SCROLL_INSENSITIVE, ResultSet.CONCUR_UPDATABLE);
 63→            ResultSet resultSet = preparedStatement.executeQuery(); // 쿼리문 전송
 64→            long queryEndTime = System.currentTimeMillis(); // 쿼리 종료 시간
 65→            logger.debug("mysql tPVShopItemBuyClick 쿼리 시간 : " + (queryEndTime - queryStartTime));
