 71→
 72→            resultSet.last(); // 커서를 맨아래로
 73→            int recodeCount = resultSet.getRow(); // 데이터 개수 체크
 74→            resultSet.beforeFirst(); // 커서를 맨위로
 75→            while (resultSet.next()) {
 76→                String cmpny_c = resultSet.getString("sShopId");
