 85→                boolean pattern_link_prod_c = Pattern.matches("^[a-zA-Z0-9-]*$", link_prod_c);
 86→
 87→                if (pattern_cmpny_c && pattern_link_prod_c) {
 88→                    String key = cmpny_c + "_" + link_prod_c;
 89→                    Integer tempScore = mapPopularityScore.get(key);
 90→                    if (tempScore == null) {
 91→                        mapPopularityScore.put(key, score);
 92→                    } else if (tempScore != null) {
 93→                        mapPopularityScore.put(key, score + tempScore);
 94→                    }
 95→                }
 96→            }
 97→            logger.info("제휴상품 인기점수 갱신 전 개수:" + recodeCount);
 98→            logger.info("제휴상품 인기점수 갱신 후 개수:" + mapPopularityScore.size());
 99→            logger.debug("mysql tPVShopItemBuyClick 수집 종료.");
100→
101→            resultSet.close();
102→            preparedStatement.close();
103→        } catch (Exception e) {
104→            logger.error("", e);
105→//            TODO 알림처리
