170→    void scoreDataBulkUpdate(String type, Map<String, Integer> mapPopularityScore, int threadSize, String index, int bulkSize) {
171→
172→        ExecutorService executorService = Executors.newFixedThreadPool(threadSize);
173→
174→        BlockingQueue queue = new LinkedBlockingQueue(threadSize * 10);
175→        //여러 쓰레드가 작업큐를 공유한다.
176→        List<Future> list = new ArrayList<>();
177→        for (int i = 0; i < threadSize; i++) {
178→            PopularityScoreUnlinkPreProcess.Worker w = new Worker(queue, index, job);
179→            list.add(executorService.submit(w));
180→        }
181→
182→        int count = 0;
183→
184→        long start = System.currentTimeMillis();
185→        BulkRequest request = new BulkRequest();
186→        long time = System.nanoTime();
187→        try {
188→            for(Map.Entry scoreSet : mapPopularityScore.entrySet()) {
189→                if (job != null && job.getStopSignal() != null && job.getStopSignal()) {
190→                    logger.info("Stop Signal");
191→                    throw new StopSignalException();
192→                }
193→
194→                Map doc = new HashMap();
195→                /**
196→                 * 초기화면 0점으로 업데이트
197→                 */
198→                if(type.equals("init")) {
199→                    doc.put("popularityScore", "0");
200→                }else{
201→                    doc.put("popularityScore", String.valueOf(scoreSet.getValue()));
202→                }
203→
204→                UpdateRequest updateRequest = new UpdateRequest().index(index);
205→                updateRequest.id(scoreSet.getKey().toString()).doc(doc);
206→                request.add(updateRequest);
207→
208→                count++;
209→
210→                if (count % bulkSize == 0) {
211→                    queue.put(request);
212→                    request = new BulkRequest();
213→                }
214→
215→                if (count % 100000 == 0) {
216→                    logger.info("index: [{}] {} ROWS FLUSHED! in {}ms", index, count, (System.nanoTime() - time) / 1000000);
217→                }
218→            }
219→
220→            if (request.estimatedSizeInBytes() > 0) {
221→                //나머지..
222→                queue.put(request);
223→                logger.info("Final bulk! {}", count);
224→            }
225→
226→
227→        } catch (InterruptedException e) {
228→            logger.error("interrupted! ", e);
229→        } catch (Exception e) {
230→            logger.error("[Exception] ", e);
231→        } finally {
232→            try {
233→                for (int i = 0; i < list.size(); i++) {
234→                    // 쓰레드 갯수만큼 종료시그널 전달.
235→                    queue.put("<END>");
236→                }
237→
238→            } catch (InterruptedException e) {
239→                logger.error("", e);
240→                //ignore
241→            }
242→
243→            try {
244→                for (int i = 0; i < list.size(); i++) {
245→                    Future f = list.get(i);
246→                    f.get();
247→                }
248→            } catch (Exception e) {
249→                logger.error("", e);
250→                //ignore
251→            }
252→
253→            // 큐 안의 내용 제거
254→            logger.info("queue clear");
255→            queue.clear();
256→
257→            // 쓰레드 종료
258→            logger.info("{} thread shutdown", index);
259→            executorService.shutdown();
260→
261→            // 만약, 쓰레드가 정상적으로 종료 되지 않는다면,
262→            if (!executorService.isShutdown()) {
263→                // 쓰레드 강제 종료
264→                logger.info("{} thread shutdown now!", index);
265→                executorService.shutdownNow();
266→            }
267→        }
268→
269→        long totalTime = System.currentTimeMillis() - start;
270→
271→        if (type.equals("init")) {
272→            logger.info("인기점수 초기화 완료하였습니다. 총 {} - 소요시간 {}m ", count, totalTime / 1000/ 60);
273→        }else{
274→            logger.info("인기점수 전처리 완료하였습니다. 총 {} - 소요시간 {}m ", count, totalTime / 1000/ 60);
275→        }
276→
277→
278→    }
