280→    public Map<String, Integer> loadScoreData(File file, Map<String,Integer> mapPopularityScore) {
281→
282→        try {
283→            logger.info("file : {} - {}", file.getPath(), file.getName());
284→            FileReader fr = new FileReader(file);
285→            BufferedReader br = new BufferedReader(fr);
286→            Map<String, Integer> scoreMap = new HashMap<>();
287→
288→            int exsistCount = 0;
289→            String rline = null;
290→            while((rline = br.readLine()) != null) {
291→
292→                //ob[0] = 검색상품 키
293→                //ob[1] = 제휴상품 인기점수
294→                String[] scoreArr = rline.split("\t");
295→
296→                //전날 데이터와 금일 데이터에 모두 있는 상품은 초기화 할 필요가 없으므로 scoreMap에 담지 않는다.
297→                if(scoreArr.length == 2 && mapPopularityScore.get(scoreArr[0]) == null) {
298→                    scoreMap.put(scoreArr[0], Integer.parseInt(scoreArr[1]));
299→                }else if (mapPopularityScore.get(scoreArr[0]) != null) {
300→                    exsistCount++;
301→                }
302→            }
303→
304→            br.close();
305→            fr.close();
306→            logger.info("제휴상품이 어제와 동일하게 존재하는 사움 개수 : {}", exsistCount);
307→            return scoreMap;
308→
309→        } catch (FileNotFoundException e) {
310→            logger.error("file not found : {}" ,e.getMessage());
311→        } catch (IOException e) {
312→            logger.error("load score file error : {}" ,e.getMessage());
313→        }
314→
315→        return null;
316→    }
