318→    void writeScoreData(Map<String,Integer> mapPopularityScore, File file) {
319→
320→        try {
321→            /**
322→             *  기존파일 있을 경우 지우고 새로 생성
323→             */
324→            if(file.exists()) {
325→                file.delete();
326→            }
327→            file.createNewFile();
328→            FileWriter fw = new FileWriter(file);
329→            BufferedWriter bw = new BufferedWriter(fw);
330→
331→            logger.info("scoreMap Size : {}", mapPopularityScore.size());
332→            for(Map.Entry entry : mapPopularityScore.entrySet()) {
333→                bw.write(entry.getKey()+"\t"+entry.getValue());
334→                bw.newLine();
335→            }
336→
337→            bw.close();
338→            fw.close();
339→
340→        } catch (IOException e) {
341→            logger.error("write score file error : {}" ,e.getMessage());
342→        }
343→    }
