345→    class Worker implements Callable {
346→        private BlockingQueue queue;
347→        private int sleepTime = 1000;
348→        private boolean isStop = false;
349→        private String index;
350→        private Job job;
351→        private int requestCount;
352→        private int docMissingCount = 0;
353→
354→        public Worker(BlockingQueue queue, String index, Job job) {
355→            this.queue = queue;
356→            this.index = index;
357→            this.job = job;
358→        }
359→
360→        private void retry(BulkRequest bulkRequest) {
361→            // 동기 방식
362→            try (RestHighLevelClient client = new RestHighLevelClient(builder)) {
363→
364→                BulkResponse bulkResponse;
365→                // 문서 손실 방지. es rejected 에러시 무한 색인 요청
366→                while (true) {
367→                    bulkResponse = client.bulk(bulkRequest, RequestOptions.DEFAULT);
368→
369→                    BulkRequest retryBulkRequest = new BulkRequest();
370→                    requestCount = bulkResponse.getItems().length;
371→                    if (bulkResponse.hasFailures()) {
372→
373→                        // bulkResponse에 에러가 있다면
374→                        // retry 1회 시도
375→                        BulkItemResponse[] bulkItemResponses = bulkResponse.getItems();
376→                        List<DocWriteRequest<?>> requests = bulkRequest.requests();
377→                        for (int i = 0; i < bulkItemResponses.length; i++) {
378→                            BulkItemResponse bulkItemResponse = bulkItemResponses[i];
379→
380→                            if (bulkItemResponse.isFailed()) {
381→                                BulkItemResponse.Failure failure = bulkItemResponse.getFailure();
382→                                // write queue reject 이슈 코드 = ( 429 )
383→                                if (failure.getStatus() == RestStatus.fromCode(429)) {
384→//                                logger.error("write queue rejected!! >> {}", failure);
385→
386→                                    // retry bulk request에 추가
387→                                    // bulkRequest에 대한 response의 순서가 동일한 샤드에 있다면 보장.
388→                                    // https://discuss.elastic.co/t/is-the-execution-order-guaranteed-in-a-single-bulk-request/100412
389→                                    retryBulkRequest.add(requests.get(i));
390→                                } else {
391→                                    if (failure.getMessage().contains("document missing")) {
392→                                        docMissingCount++;
393→                                    }
394→                                    //logger.error("Doc index error >> {}", failure);
395→                                }
396→                            }
397→                        }
398→
399→                    }
400→
401→                    if (retryBulkRequest.requests().size() == 0) {
402→                        break;
403→                    } else {
404→                        logger.info("Retry Bulk Size {}", bulkRequest.requests().size());
405→                        bulkRequest = retryBulkRequest;
406→                    }
407→
408→                    if (job.getStopSignal()) {
409→                        throw new StopSignalException();
410→                    }
411→                }
412→
413→                logger.info("Bulk Success : index:{} - request:{} - doc mssing:{} - elapsed:{}", index, requestCount, docMissingCount , bulkResponse.getTook());
414→                docMissingCount=0;
415→            } catch (Exception e) {
416→                logger.error("retry", e);
417→            }
418→        }
419→
420→
421→        @Override
422→        public Object call() {
423→
424→            try {
425→                while (true) {
426→                    Object o = queue.take();
427→                    if (o instanceof String) {
428→                        //종료.
429→                        logger.info("Indexing Worker-{} index={} got {}", Thread.currentThread().getId(),index,o);
430→                        break;
431→                    }
432→                    BulkRequest request = (BulkRequest) o;
433→                    retry(request);
434→                    logger.debug("remained queue : {}", queue.size());
435→
436→                }
437→            } catch (Throwable e) {
438→                logger.error("indexParallel : {}", e);
439→            }
440→
441→            return null;
442→        }
443→    }
444→}
